def _graphql_op(req: Any) -> Any:
    """operationName / persisted-query hash of a GraphQL request (POST body or GET query)."""
    try:
        body = json.loads(req.body) if req.body else {}
    except (ValueError, TypeError):
        body = {}
    if not isinstance(body, dict) or not body:
        from urllib.parse import parse_qsl

        body = dict(parse_qsl(urlsplit(req.url).query))
        if isinstance(body.get("extensions"), str):
            try:
                body["extensions"] = json.loads(body["extensions"])
            except ValueError:
                pass
    ext = body.get("extensions") if isinstance(body.get("extensions"), dict) else {}
    pq = ext.get("persistedQuery") if isinstance(ext, dict) else None
    return body.get("operationName") or (pq.get("sha256Hash") if isinstance(pq, dict) else None)


def route_of(req: Any, routes: dict[str, list[Any]]) -> Any:
    path = urlsplit(req.url).path
    for name, (method, rx, op) in routes.items():
        if req.method == method and re.match(rx, path) and (op is None or _graphql_op(req) == op):
            return name
    return None


