def _token_response(n: int) -> dict[str, Any]:
    flow = CLIENT.AUTH_FLOW
    body: dict[str, Any] = {}
    client_mod.set_path(body, flow["token_path"].split("."), f"tok-{n}-not-real")
    if flow.get("refresh_token_path"):
        client_mod.set_path(body, flow["refresh_token_path"].split("."), f"rt-{n}-not-real")
    if flow.get("expires_in_path"):
        client_mod.set_path(body, flow["expires_in_path"].split("."), 3600)
    return body


class TokenServer(FakeTransport):
    """Issues tok-1 at login, rejects it once (401), issues tok-2 on refresh."""

    def __init__(self) -> None:
        super().__init__()
        self.rejected = False

    def __call__(self, req: Any) -> Any:
        flow = CLIENT.AUTH_FLOW
        role = route_of(req, AUTH_ROUTES)
        ok = {"content-type": "application/json"}
        if role == flow["login_endpoint"]:
            self.calls.append(req)
            return client_mod.RawResponse(200, ok, json.dumps(_token_response(1)).encode(), req.url)
        if role == flow.get("refresh_endpoint"):
            self.calls.append(req)
            assert b"rt-1-not-real" in (req.body or b"") or "rt-1-not-real" in req.url
            return client_mod.RawResponse(200, ok, json.dumps(_token_response(2)).encode(), req.url)
        sent = json.dumps(dict(req.headers)) + req.url
        if "tok-1-not-real" in sent and not self.rejected:
            self.calls.append(req)
            self.rejected = True
            return client_mod.RawResponse(401, ok, b'{"error": "expired"}', req.url)
        assert "tok-2-not-real" in sent or "tok-1-not-real" in sent, "learned token was not sent"
        return super().__call__(req)


def test_auth_flow_login_use_and_refresh_on_401() -> None:
    client_mod.CircuitBreaker.reset_all()
    t = TokenServer()
    api = CLIENT(transport=t, min_interval=0, respect_robots=False, max_retries=0, auth={})
    api.authenticate()
    api.get_me(**{})
    roles = [route_of(c, AUTH_ROUTES) or route_of(c, ROUTES) for c in t.calls]
    flow = CLIENT.AUTH_FLOW
    assert roles == [flow["login_endpoint"], 'get_me', flow["refresh_endpoint"], 'get_me'], roles
    assert "tok-2-not-real" in json.dumps(dict(t.calls[-1].headers)) + t.calls[-1].url


