def test_auth_never_sent_to_foreign_hosts(api: Any) -> None:
    api.auth["authorization"] = "Bearer test-token-not-real"
    try:
        api.request("GET", "https://example.org/x")
    except client_mod.MimicError:
        pass
    foreign = [c for c in api.fake.calls if urlsplit(c.url).hostname == "example.org"]
    assert foreign and "authorization" not in {k.lower() for k in foreign[0].headers}
